contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 reqAmount, uint256 reqInterest, uint256 reqLoanToCollateral, uint256 reqDuration, bool direct, address newLender) public payable {
        require(reqLoanToCollateral != 0, "div by zero");

        c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration);
        uint256 loanID = c.clearRequest(0, direct, false);

        C.Loan memory loanBefore = c.getLoan(loanID);

        bool revertUnauthorized;
        try c.setDirectRepay(loanID, !direct) {
            revertUnauthorized = false;
        } catch {
            revertUnauthorized = true;
        }

        bool revertApprove;
        try c.approveTransfer(newLender, loanID) {
            revertApprove = false;
        } catch {
            revertApprove = true;
        }

        bool revertTransfer;
        try c.transferOwnership(loanID) {
            revertTransfer = false;
        } catch {
            revertTransfer = true;
        }

        C.Loan memory loanAfter = c.getLoan(loanID);

        if (msg.sender == loanBefore.lender) {
            assert(!revertUnauthorized && !revertApprove && !revertTransfer && loanAfter.lender == msg.sender);
        } else {
            assert(revertUnauthorized && revertApprove && revertTransfer && loanAfter.lender == loanBefore.lender);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 reqAmount,
        uint256 reqInterest,
        uint256 reqLoanToCollateral,
        uint256 reqDuration,
        bool direct,
        address newLender,
        bool newDirect,
        uint256 loanID
    ) public payable {
        require(reqLoanToCollateral != 0, "div by zero");
        require(loanID != 0, "zero loan id");

        c.requestLoan(reqAmount, reqInterest, reqLoanToCollateral, reqDuration);

        uint256 createdLoanID = c.clearRequest(0, direct, false);

        C.Loan memory loanBefore = c.getLoan(createdLoanID);

        bool revertedSetDirect;
        try c.setDirectRepay(createdLoanID, newDirect) {
            revertedSetDirect = false;
        } catch {
            revertedSetDirect = true;
        }

        bool revertedApprove;
        try c.approveTransfer(newLender, createdLoanID) {
            revertedApprove = false;
        } catch {
            revertedApprove = true;
        }

        bool revertedTransfer;
        try c.transferOwnership(createdLoanID) {
            revertedTransfer = false;
        } catch {
            revertedTransfer = true;
        }

        C.Loan memory loanAfter = c.getLoan(createdLoanID);

        if (msg.sender != loanBefore.lender) {
            assert(
                revertedSetDirect &&
                    revertedApprove &&
                    revertedTransfer &&
                    loanAfter.lender == loanBefore.lender
            );
        } else {
            assert(true);
        }
    }
}

