contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_, bool repayDirect_, bool isCallback_) public payable {
        require(amount_ > 0 && loanToCollateral_ > 0 && duration_ > 0, "precondition");
        bool ok1;
        try c.requestLoan(amount_, interest_, loanToCollateral_, duration_) { ok1 = true; } catch { ok1 = false; }
        require(ok1, "request setup");

        bool reverted;
        try c.clearRequest(0, repayDirect_, isCallback_) { reverted = false; } catch { reverted = true; }

        if (isCallback_) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }

    receive() external payable {}
}

