contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration,
        bool repayDirect,
        bool isCallback
    ) public {
        require(amount > 0);
        require(loanToCollateral > 0);
        require(duration > 0);

        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        ERC20 debtToken = c.debt();
        address owner = c.owner();

        uint256 ownerBefore = debtToken.balanceOf(owner);

        uint256 loanID = c.clearRequest(reqID, repayDirect, isCallback);

        uint256 ownerAfter = debtToken.balanceOf(owner);
        C.Loan memory loan = c.getLoan(loanID);

        assert(
            ownerAfter == ownerBefore + amount &&
            loan.amount == amount + c.interestFor(amount, interest, duration) &&
            loan.collateral == c.collateralFor(amount, loanToCollateral) &&
            loan.lender == address(this) &&
            loan.repayDirect == repayDirect &&
            loan.callback == isCallback &&
            !c.isActive(reqID)
        );
    }
}

