contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 duration_,
        uint256 loanToCollateral_
    ) public payable {
        require(amount_ > 0);
        require(loanToCollateral_ > 0);
        require(duration_ > 0);

        // Ensure collateralFor is exact (no truncation) by requiring divisibility.
        require((amount_ * (10 ** c.collateral().decimals())) % loanToCollateral_ == 0);

        c.requestLoan(amount_, 0, loanToCollateral_, duration_);

        uint256 loanID = c.clearRequest(0, false, false);

        C.Loan memory loan = c.getLoan(loanID);
        uint256 expectedCollateral = c.collateralFor(loan.request.amount, loan.request.loanToCollateral);

        assert(loan.collateral == expectedCollateral);
    }

    receive() external payable {}
}

