contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_
    ) public payable {
        require(amount_ > 0 && amount_ < 1e24);
        require(interest_ < 1e18);
        require(loanToCollateral_ > 0 && loanToCollateral_ < 1e24);
        require(duration_ >= 1 && duration_ < 365 days);

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);
        uint256 loanID = c.clearRequest(reqID, false, false);

        C.Loan memory beforeLoan = c.getLoan(loanID);
        require(beforeLoan.collateral > 0);

        bool expired = block.timestamp > beforeLoan.expiry;
        uint256 beforeCollateral = beforeLoan.collateral;
        uint256 beforeAmount = beforeLoan.amount;
        address beforeLender = beforeLoan.lender;

        bool reverted;
        uint256 amt;
        uint256 coll;
        uint256 elapsed;
        try c.claimDefaulted(loanID) returns (uint256 a, uint256 b, uint256 e) {
            reverted = false;
            amt = a;
            coll = b;
            elapsed = e;
        } catch {
            reverted = true;
        }

        C.Loan memory afterLoan = c.getLoan(loanID);

        if (!expired) {
            assert(
                reverted &&
                afterLoan.amount == beforeAmount &&
                afterLoan.collateral == beforeCollateral &&
                afterLoan.lender == beforeLender
            );
        } else {
            assert(
                !reverted &&
                amt == beforeAmount &&
                coll == beforeCollateral &&
                afterLoan.amount == 0 &&
                afterLoan.collateral == 0
            );
        }
    }

    receive() external payable {}
}

contract InvMutTest {
