    }

    function run(
        address owner_,
        address lender_,
        address other_,
        uint256 amount_,
        uint256 interest_,
        uint256 loanToCollateral_,
        uint256 duration_,
        uint256 repayAmount_,
        bool useRepay
    ) public payable {
        require(owner_ != address(0) && lender_ != address(0) && other_ != address(0));
        require(owner_ != lender_ && owner_ != other_ && lender_ != other_);
        require(amount_ > 0 && amount_ < type(uint256).max / 2);
        require(loanToCollateral_ > 0);
        require(duration_ > 0 && duration_ < type(uint256).max / 2);

        ERC20 coll = c.collateral();
        ERC20 debt = c.debt();
        uint256 collBal = coll.balanceOf(address(this));
        uint256 debtBal = debt.balanceOf(address(this));
        require(collBal >= amount_ && debtBal >= amount_);
        require(coll.transfer(address(c), type(uint256).max));
        require(debt.transfer(address(c), type(uint256).max));

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        uint256 interest = c.interestFor(amount_, interest_, duration_);
        uint256 loanID = c.clearRequest(reqID, false, false);

        uint256 debtBeforeClaim = debt.balanceOf(lender_);

        uint256 loanAmountBefore;
        uint256 loanUnclaimedBefore;
        uint256 loanCollateralBefore;
        (
            loanAmountBefore,
            loanUnclaimedBefore,
            loanCollateralBefore
        ) = c.loans(loanID);

        uint256 repaid = 0;
        if (useRepay) {
            repaid = repayAmount_;
            if (repaid > loanAmountBefore) repaid = loanAmountBefore;
        }

        if (repaid > 0) {
            c.repayLoan(loanID, repaid);
        }

        uint256 unclaimedBeforeClaim = 0;
        if (useRepay) {
            unclaimedBeforeClaim = c.loans(loanID).unclaimed;
        }

        uint256 expectedTransfer = useRepay ? unclaimedBeforeClaim : 0;

        c.claimRepaid(loanID);

        uint256 debtAfterClaim = debt.balanceOf(lender_);

        assert(debtAfterClaim >= debtBeforeClaim);
        assert(debtAfterClaim - debtBeforeClaim == expectedTransfer);
    }

    receive() external payable {}
}

