        c = _c;
    }

    function run(uint256 reqAmount_, uint256 reqInterest_, uint256 reqLoanToCollateral_, uint256 reqDuration_, bool repayDirect_, uint256 repaid_) public payable {
        require(reqAmount_ > 0, "amount must be positive");
        require(reqLoanToCollateral_ > 0, "ratio must be positive");
        require(reqDuration_ > 0, "duration must be positive");

        c.requestLoan(reqAmount_, reqInterest_, reqLoanToCollateral_, reqDuration_);
        uint256 reqID = 0;

        uint256 clearLoanID = c.clearRequest(reqID, repayDirect_, false);

        C.Loan memory loanBefore = c.getLoan(clearLoanID);
        uint256 loanAmountBefore = loanBefore.amount;
        uint256 loanCollateralBefore = loanBefore.collateral;

        require(loanAmountBefore > 0, "loan amount must be positive");
        require(loanCollateralBefore > 0, "loan collateral must be positive");

        uint256 repayAmount = repaid_ % (loanAmountBefore + 1);
        require(repayAmount > 0, "repayment must be positive");

        uint256 decollateralized = c.repayLoan(clearLoanID, repayAmount);

        assert(decollateralized == (loanCollateralBefore * repayAmount) / loanAmountBefore);
    }

    receive() external payable {}
}

