    }

    function run(uint256 amount_, uint256 interest_, uint256 loanToCollateral_, uint256 duration_) public {
        require(true);

        uint256 reqID = c.requestLoan(amount_, interest_, loanToCollateral_, duration_);

        bool cleared;
        try c.clearRequest(reqID, false, false) {
            cleared = true;
        } catch {
            cleared = false;
        }

        require(cleared, "clear must succeed for a valid fresh request");

        bool reverted;
        try c.approveTransfer(address(this), 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }
